/* Unit checks (Daily Teaching System, Part 7): two short paper checks per unit, built from the unit's own worksheets.
 *
 *   content/assessments/checks.<loc>.json   GENERATED by scripts/assessments/assemble.js
 *   content/assessments/ui.<loc>.json       the strings of the section and of the printed pages
 *
 * The student forms are printables like any worksheet (GET /api/quota/dl?kind=form, counted as a download); the
 * answer keys and the teacher pages are Teacher-only files (kind=teacher). A check is shown on its unit's page when
 * its status is live. */
export interface CheckPart { part: number; lesson: number; title: string; type: string; tasks: number }
export interface UnitCheck {
  unit: string;
  slug: string;
  status: 'pilot' | 'live';
  parts: CheckPart[];
  notCovered: number[];
  forms: { A: { pages: number }; B: { pages: number } };
  /** (Wave 4) the writing part of a writing unit, scored with the guide on the teacher pages: 0–2 per point */
  writing?: { part: number; points: { id: string; kind: string; max: number }[] };
}
export type AssessmentUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T | null;
  try { const mod = await importer(); cache.set(key, mod.default); } catch { cache.set(key, null); }
  return cache.get(key) as T | null;
}

export const getAssessmentUi = (locale: string) => load<AssessmentUi>(`ui.${locale}`, () => import(`@/content/assessments/ui.${locale}.json`));

/** the check of a unit that the page may show: a live one, or none */
export async function getUnitCheck(locale: string, unitId: string): Promise<UnitCheck | null> {
  const f = await load<{ checks: UnitCheck[] }>(`checks.${locale}`, () => import(`@/content/assessments/checks.${locale}.json`));
  const c = f?.checks.find((x) => x.unit === unitId);
  return c && c.status === 'live' ? c : null;
}

/** the live checks of a language (the assessments hub lists them) */
export async function listedChecks(locale: string): Promise<UnitCheck[]> {
  const f = await load<{ checks: UnitCheck[] }>(`checks.${locale}`, () => import(`@/content/assessments/checks.${locale}.json`));
  return (f?.checks ?? []).filter((c) => c.status === 'live');
}

/** a student form: a printable, counted like any download */
export const checkFormHref = (locale: string, unitId: string, form: 'a' | 'b') => `/api/quota/dl?kind=form&loc=${locale}&file=${encodeURIComponent(`checks/${unitId}/check-${form}`)}`;

/* (Stage C-2, 2026-11-22) THE CHECKS OF THE YEAR: per grade and subject a check of the beginning, the middle and the
 * end of the year, each a list of parts that are lessons of the year's units (content/assessments/year.<loc>.json,
 * GENERATED by scripts/assessments/assemble.js --year). Their files lie where a unit check's lie (checks/<id>/…), so the
 * same metered path hands out their student forms and the same gate their Teacher-only files. English only for now; a
 * page of a grade and subject shows its live checks, and has no page while none is live. */
export const YEAR_LOCALES = ['en'] as const;
export const YEAR_TIMES = ['beginning', 'middle', 'end'] as const;
export type YearTime = (typeof YEAR_TIMES)[number];
export interface YearPart { part: number; unit: string; unitSlug: string; lesson: number; key: string; title: string; type: string; tasks: number }
export interface YearCheck {
  id: string;
  grade: string;
  subject: string;
  time: YearTime;
  slug: string;
  plan: string;
  status: 'pilot' | 'live';
  parts: YearPart[];
  forms: { A: { pages: number }; B: { pages: number } };
}
/** one page: a grade and a subject with its live checks, in the order beginning, middle, end */
export interface YearPage { slug: string; grade: string; subject: string; checks: YearCheck[] }

async function liveYearChecks(locale: string): Promise<YearCheck[]> {
  if (!(YEAR_LOCALES as readonly string[]).includes(locale)) return [];
  const f = await load<{ checks: YearCheck[] }>(`year.${locale}`, () => import(`@/content/assessments/year.${locale}.json`));
  return (f?.checks ?? []).filter((c) => c.status === 'live');
}

/** the pages of the checks of the year that a language has: a grade and subject with at least one live check */
export async function listedYearPages(locale: string): Promise<YearPage[]> {
  const pages: YearPage[] = [];
  for (const c of await liveYearChecks(locale)) {
    let p = pages.find((x) => x.slug === c.slug);
    if (!p) { p = { slug: c.slug, grade: c.grade, subject: c.subject, checks: [] }; pages.push(p); }
    p.checks.push(c);
  }
  for (const p of pages) p.checks.sort((a, b) => YEAR_TIMES.indexOf(a.time) - YEAR_TIMES.indexOf(b.time));
  return pages;
}

export async function getYearPage(locale: string, slug: string): Promise<YearPage | null> {
  return (await listedYearPages(locale)).find((p) => p.slug === slug) ?? null;
}

/* (Stage C-3, 2026-11-23) THE PLACEMENT CHECKS: one per skill path, a ladder of steps across grades, each step a lesson of a
 * unit (content/assessments/placement.<loc>.json, GENERATED by scripts/assessments/assemble.js --placement). The teacher gives
 * the steps in order and stops where the child stops; the step names the unit and lesson to start at. Their files lie where a
 * unit check's lie (checks/<id>/…). English only for now; a page shows a live check, and there is no page while it is not. */
export const PLACEMENT_LOCALES = ['en'] as const;
export interface PlacementStep { step: number; unit: string; unitSlug: string; lesson: number; key: string; title: string; type: string; grade: string; tasks: number }
export interface PlacementCheck {
  id: string;
  path: string;
  subject: string;
  slug: string;
  grades: string[];
  status: 'pilot' | 'live';
  steps: PlacementStep[];
  writing?: { part: number; points: { id: string; kind: string; max: number }[] };
  forms: { A: { pages: number }; B: { pages: number } };
}

/** the live placement checks of a language, in the order of their blueprint */
export async function listedPlacement(locale: string): Promise<PlacementCheck[]> {
  if (!(PLACEMENT_LOCALES as readonly string[]).includes(locale)) return [];
  const f = await load<{ checks: PlacementCheck[] }>(`placement.${locale}`, () => import(`@/content/assessments/placement.${locale}.json`));
  return (f?.checks ?? []).filter((c) => c.status === 'live');
}

export async function getPlacement(locale: string, slug: string): Promise<PlacementCheck | null> {
  return (await listedPlacement(locale)).find((c) => c.slug === slug) ?? null;
}
